<?php
declare(strict_types=1); require dirname(__DIR__,2).'/app/bootstrap.php'; $user=Auth::requireLogin(); Auth::requirePermission('companies.manage'); $pdo=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$name=trim($_POST['name']??'');$slug=strtolower(trim($_POST['slug']??''));$type=in_array($_POST['company_type']??'transport',['transport','agent'],true)?$_POST['company_type']:'transport';if(mb_strlen($name)<2||!preg_match('/^[a-z0-9-]{2,190}$/',$slug))$error='أدخل اسم الشركة ومعرّفاً لاتينياً صالحاً.';else try{$pdo->prepare('INSERT INTO companies(name,slug,company_type,description,phone,whatsapp,status) VALUES(?,?,?,?,?,?,?)')->execute([$name,$slug,$type,trim($_POST['description']??''),trim($_POST['phone']??''),trim($_POST['whatsapp']??''),'active']);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO activity_logs(user_id,action_key,entity_type,entity_id,description,ip_address) VALUES(?,?,?,?,?,?)')->execute([$user['id'],'company.created','company',$id,'إضافة شركة '.$name,$_SERVER['REMOTE_ADDR']??null]);redirect('/admin/companies.php?created=1');}catch(Throwable){$error='تعذر حفظ الشركة. تأكد من عدم تكرار المعرّف.';}}
$rows=$pdo->query('SELECT id,name,slug,company_type,status,phone FROM companies ORDER BY id DESC')->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>شركات النقل</title><link rel="stylesheet" href="/assets/css/app.css"><style>.wrap{padding:25px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}table{width:100%;border-collapse:collapse;white-space:nowrap}td,th{text-align:right;padding:12px;border-bottom:1px solid #eee;font-size:13px}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><header class="site-header"><a class="brand" href="/admin/index.php"><span class="brand-mark">م</span><b>شركات النقل</b></a><a href="/admin/index.php">لوحة التحكم</a></header><main class="wrap"><h1>إدارة الشركات والوكلاء</h1><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><?php if(isset($_GET['created'])):?><p class="notice">تمت إضافة الشركة.</p><?php endif;?><section class="panel"><form method="post" class="grid"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><label>اسم الشركة<input name="name" required></label><label>المعرّف (بالإنجليزية)<input name="slug" placeholder="company-name" required pattern="[a-z0-9-]{2,190}"></label><label>النوع<select name="company_type"><option value="transport">شركة نقل</option><option value="agent">وكيل</option></select></label><label>الهاتف<input name="phone"></label><label>واتساب<input name="whatsapp"></label><label>الوصف<input name="description"></label><button class="btn btn-primary" type="submit">إضافة الشركة</button></form></section><section class="panel"><table><thead><tr><th>الشركة</th><th>المعرّف</th><th>النوع</th><th>الهاتف</th><th>الحالة</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slug'])?></td><td><?=e($r['company_type'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>